select COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6 and lo_quantity>=26 and lo_quantity<=35;
select p_mfgr, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6 and lo_quantity>=26 and lo_quantity<=35 group by p_mfgr;
select p_mfgr, p_category, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6  and lo_quantity>=26 and lo_quantity<=35 group by p_mfgr, p_category;
select p_mfgr, p_category, p_type, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6  and lo_quantity>=26 and lo_quantity<=35 group by p_mfgr, p_category, p_type;
select p_mfgr, p_category, p_type, p_brand1, COUNT(*) from lineorder, dwdate, part, supplier where lo_orderdate = d_datekey and lo_partkey = p_partkey and lo_suppkey = s_suppkey and s_region = 'AMERICA' and d_weeknuminyear = 6  and lo_quantity>=26 and lo_quantity<=35 group by p_mfgr, p_category, p_type, p_brand1;
